<html lang="en">
<head><meta charset="utf-8"><style>
body{font-family:dejavusans,sans-serif;color:#202b36;font-size:10pt}h1{font-size:22pt;margin:0;color:#145b73}.muted{color:#687782}.top{border-bottom:2px solid #145b73;padding-bottom:14px;margin-bottom:22px}.right{text-align:right}.brand-logo{width:145px;height:auto;max-height:60px;object-fit:contain}.items{width:100%;border-collapse:collapse;margin-top:24px}.items th{background:#edf3f5;text-align:left}.items th,.items td{padding:9px;border-bottom:1px solid #d9e1e5}.totals{width:42%;margin:18px 0 0 auto;border-collapse:collapse}.totals td{padding:5px}.grand{font-weight:bold;border-top:1px solid #80919a}.note{margin-top:25px;padding:12px;background:#f3f6f7}
