<body>
    <table width="100%" class="top table-bordered"><tr><td width="45%">@if ($logoData)<img class="brand-logo" src="data:image/png;base64,{{ $logoData }}" alt="OMG Computer">@else<strong>OMG Computer</strong>@endif</td><td><h1>{{ $document->type === 'quotation' ? 'Quotation' : 'Invoice' }}</h1><div class="muted">{{ $document->number }}</div></td><td class="right">{{ $document->issue_date->format('F j, Y') }}</td></tr></table>
    <table width="100%" class="table-bordered"><tr><td width="55%"><div class="muted">BILL TO</div><strong>{{ $document->customer_name }}</strong><br>{{ $document->customer_email }}<br>{{ $document->customer_phone }}<br>{!! nl2br(e($document->customer_address)) !!}</td><td class="right"><div class="muted">DUE DATE</div>{{ $document->due_date?->format('F j, Y') ?? 'On receipt' }}<br><div class="muted" style="margin-top:8px">STATUS</div>{{ ucfirst(str_replace('_', ' ', $document->status)) }}</td></tr></table>
    <table class="items table-bordered"><thead><tr><th>Description</th><th class="right">Qty</th><th class="right">Unit price</th><th class="right">Amount</th></tr></thead><tbody>@foreach ($document->items as $item)<tr><td>{{ $item->description }}</td><td class="right">{{ $item->quantity }}</td><td class="right">RM {{ number_format($item->unit_price, 2) }}</td><td class="right">RM {{ number_format($item->line_total, 2) }}</td></tr>@endforeach</tbody></table>
    <table class="totals table-bordered"><tr><td>Subtotal</td><td class="right">RM {{ number_format($document->subtotal, 2) }}</td></tr><tr><td>Tax ({{ number_format($document->tax_rate, 2) }}%)</td><td class="right">RM {{ number_format($document->tax_amount, 2) }}</td></tr><tr class="grand"><td>Total</td><td class="right">RM {{ number_format($document->total, 2) }}</td></tr><tr><td>Paid</td><td class="right">RM {{ number_format($document->paid_amount, 2) }}</td></tr><tr><td>Balance</td><td class="right">RM {{ number_format($document->balance, 2) }}</td></tr></table>
